        if (!words.count(endWord)) {
            return ans;
        }
        words.erase(beginWord);
        unordered_map<string, int> dist{{beginWord, 0}};
        unordered_map<string, unordered_set<string>> prev;
        queue<string> q{{beginWord}};
        bool found = false;
        int step = 0;
        while (!q.empty() && !found) {
            ++step;
            for (int i = q.size(); i > 0; --i) {
                string p = q.front();
                q.pop();
                string t = p;
                for (int j = 0; j < t.size(); ++j) {
                    char ch = t[j];
                    for (char k = 'a'; k <= 'z'; ++k) {
                        t[j] = k;
                        if (dist.count(t) && dist[t] == step) {
                            prev[t].insert(p);
                        }
                        if (!words.count(t)) {
                            continue;
                        }
                        prev[t].insert(p);
                        words.erase(t);
                        q.push(t);
                        dist[t] = step;
                        if (t == endWord) {
                            found = true;
                        }
                    }
                    t[j] = ch;
                }
            }
        }
        function<void(vector<string>&, const string&)> dfs = [&](vector<string>& path, const string& cur) {
            if (cur == beginWord) {
                ans.emplace_back(path.rbegin(), path.rend());
                return;
            }
            for (const string& precursor : prev[cur]) {
                path.push_back(precursor);
                dfs(path, precursor);
                path.pop_back();
            }
        };
        if (found) {
            vector<string> path{endWord};
            dfs(path, endWord);
        }
        return ans;
    }
};

func findLadders(beginWord string, endWord string, wordList []string) [][]string {
	var ans [][]string
	words := make(map[string]bool)
	for _, word := range wordList {
		words[word] = true
	}
	if !words[endWord] {
		return ans
	}
	words[beginWord] = false
	dist := map[string]int{beginWord: 0}
	prev := map[string]map[string]bool{}
	q := []string{beginWord}
	found := false
	step := 0
	for len(q) > 0 && !found {
		step++
		for i := len(q); i > 0; i-- {
			p := q[0]
			q = q[1:]
			chars := []byte(p)
			for j := 0; j < len(chars); j++ {
				ch := chars[j]
				for k := 'a'; k <= 'z'; k++ {
					chars[j] = byte(k)
					t := string(chars)
					if v, ok := dist[t]; ok {
						if v == step {
							prev[t][p] = true
						}
					}
					if !words[t] {
						continue
					}
					if len(prev[t]) == 0 {
						prev[t] = make(map[string]bool)
					}
					prev[t][p] = true
					words[t] = false
					q = append(q, t)
					dist[t] = step
					if endWord == t {
						found = true
					}
				}
				chars[j] = ch
			}
		}
	}
	var dfs func(path []string, begin, cur string)
	dfs = func(path []string, begin, cur string) {
		if cur == beginWord {
			cp := make([]string, len(path))
			copy(cp, path)
			ans = append(ans, cp)
			return
		}
		for k := range prev[cur] {
			path = append([]string{k}, path...)
			dfs(path, beginWord, k)
			path = path[1:]
		}
	}
	if found {
		path := []string{endWord}
		dfs(path, beginWord, endWord)
	}
	return ans
}

